function parseScore(text) {
  const score = Number(text);
  if (!Number.isFinite(score)) {
    throw new TypeError("Score must be a number");
  }
  return score;
}

try {
  console.log(parseScore("91"));
} catch (error) {
  console.error(error.message);
}

