// progress.js
export function saveProgress(progress) {
  localStorage.setItem("academy-progress", JSON.stringify(progress));
}

export function loadProgress() {
  const raw = localStorage.getItem("academy-progress");
  return raw ? JSON.parse(raw) : {};
}

